import{_ as e}from"./chunks/plugin-vue_export-helper.DlAUqK2U.js";import{c as a,o as r,af as n}from"./chunks/mermaid.DEOxUarQ.js";import"./chunks/cytoscape.C2CwDKBM.js";import"./chunks/dayjs.C32PoDnw.js";const b=JSON.parse('{"title":"通义灵码实战 Cookbook","description":"已经装好通义灵码 / Qoder CN 之后：怎么选会话模式、怎么写需求、怎么让智能体跑终端、怎么接 MCP。","frontmatter":{"title":"通义灵码实战 Cookbook","description":"已经装好通义灵码 / Qoder CN 之后：怎么选会话模式、怎么写需求、怎么让智能体跑终端、怎么接 MCP。","domain":"product","tags":["coding-agent"],"role":"cookbook"},"headers":[],"relativePath":"zh/products/lingma/lingma-cookbook.md","filePath":"zh/products/lingma/lingma-cookbook.md","lastUpdated":1787110548000}'),o={name:"zh/products/lingma/lingma-cookbook.md"};function l(s,t,i,p,d,h){return r(),a("div",null,[...t[0]||(t[0]=[n(`<h1 id="通义灵码实战-cookbook" tabindex="-1">通义灵码实战 Cookbook <a class="header-anchor" href="#通义灵码实战-cookbook" aria-label="Permalink to &quot;通义灵码实战 Cookbook&quot;">​</a></h1><p>面向「已经登录、能补全」的读者。每个配方解决一个具体问题。安装回 <a href="./lingma.html">教程</a>；查键位回 <a href="./lingma-cheatsheet.html">Cheatsheet</a>。</p><h2 id="选对会话模式" tabindex="-1">选对会话模式 <a class="header-anchor" href="#选对会话模式" aria-label="Permalink to &quot;选对会话模式&quot;">​</a></h2><p>目标：少付「选错形态」的税。</p><table tabindex="0"><thead><tr><th>你要做的事</th><th>用哪个模式</th><th>官方依据</th></tr></thead><tbody><tr><td>解释这段 React 组件、对比两种写法</td><td><strong>智能问答</strong></td><td>「不会直接对工程文件进行修改」</td></tr><tr><td>只改点名的几个文件，自己看 diff</td><td><strong>文件编辑</strong></td><td>「精确编辑……不会做出超出开发者预期的修改」；比智能体更快</td></tr><tr><td>加一个完整功能：改文件 + 装依赖 + 跑测试</td><td><strong>智能体</strong></td><td>可拆任务、用终端、接 MCP</td></tr><tr><td>在 Lingma IDE / JetBrains 里做多文件修改</td><td><strong>智能体</strong>（不要找文件编辑）</td><td>官方：这两端不支持文件编辑</td></tr><tr><td>在 Visual Studio 里</td><td><strong>智能问答</strong></td><td>官方：VS 暂仅问答</td></tr></tbody></table><p>判断口诀：你能不能一眼看出它改错了。能 → 智能体；不能 → 退回问答，先要方案。</p><p>来源：<a href="https://help.aliyun.com/zh/lingma/overview-of-chat" target="_blank" rel="noreferrer">智能会话概览</a>、<a href="https://help.aliyun.com/zh/lingma/edit" target="_blank" rel="noreferrer">文件编辑</a>、<a href="https://help.aliyun.com/zh/lingma/agent" target="_blank" rel="noreferrer">智能体</a>。</p><h2 id="把需求写成官方建议的结构" tabindex="-1">把需求写成官方建议的结构 <a class="header-anchor" href="#把需求写成官方建议的结构" aria-label="Permalink to &quot;把需求写成官方建议的结构&quot;">​</a></h2><p>目标：少靠「再问一遍」补上下文。</p><p>官方原文（<a href="https://help.aliyun.com/zh/lingma/overview-of-chat" target="_blank" rel="noreferrer">智能会话概览</a>）：</p><blockquote><p>结构化地描述需求：首先需要澄清我们需要通义灵码帮我们做什么，建议包含一个明确的目标，并通过步骤式的结构化描述，详细地描述您期望完成的编码任务和要求。</p><p>给出相关的上下文：可以选择代码文件、图片、codebase、codeChanges 等上下文。</p><p>明确生成要求：告诉通义灵码您期望它遵循的要求，比如语言、规范、格式、变更目标等，如“生成变更时，同时为每个方法生成英文注释”。</p><p>多多互动，逐步迭代。</p></blockquote><p>可直接改的模板（结构来自上面四条，内容换成你的仓库）：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>目标：在 src/components/UserTable.tsx 给表格加上按 lastActiveAt 排序。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>步骤：</span></span>
<span class="line"><span>1. 只改现有组件，不新建页面</span></span>
<span class="line"><span>2. 默认降序，点击表头切换</span></span>
<span class="line"><span>3. 补上 TypeScript 类型，不要 any</span></span>
<span class="line"><span></span></span>
<span class="line"><span>要求：</span></span>
<span class="line"><span>- 生成变更时，同时为每个方法生成英文注释</span></span>
<span class="line"><span>- 不要改 API 层</span></span></code></pre></div><p>再在输入框里显式加上相关文件 / 图片 / codebase。Lingma IDE 的上下文<strong>暂不支持知识库</strong>（同一页官方说明）。</p><p>智能体还提供「优化输入」：先打草稿，再点优化按钮，让它结合已加上下文扩写成可执行提示（<a href="https://help.aliyun.com/zh/lingma/agent" target="_blank" rel="noreferrer">智能体</a>）。扩完仍要自己看一眼再提交。</p><h2 id="让智能体跑一个有副作用的任务" tabindex="-1">让智能体跑一个有副作用的任务 <a class="header-anchor" href="#让智能体跑一个有副作用的任务" aria-label="Permalink to &quot;让智能体跑一个有副作用的任务&quot;">​</a></h2><p>目标：端到端改代码，但终端命令仍在你手里。</p><ol><li>切到 <strong>智能体</strong>。</li><li>写清目标和边界（见上一节）。</li><li>复杂任务可等它出规划，或主动发 <code>/plan</code>（官方：智能体会对复杂任务自动生成方案；也可用 <code>/plan</code> 触发）。</li><li>终端命令弹出时，看懂再点 <strong>运行</strong>；看不懂点 <strong>取消</strong>。</li><li>在 diff 里按文件接受或拒绝。</li></ol><p>官方还允许把常用命令加入自动执行白名单（<a href="https://help.aliyun.com/zh/lingma/agent" target="_blank" rel="noreferrer">智能体</a>）：</p><blockquote><p>具体配置路径为插件 <strong>Chat</strong> 设置页面的 <strong>Auto-Run</strong> 区域，在 <strong>Terminal in Agent Mode</strong> 下方的输入框中添加允许自动运行的命令。如需添加多个命令，可以使用英文逗号分隔。</p></blockquote><p>第一周不要把 <code>rm</code>、<code>git push</code>、<code>npm publish</code> 放进白名单。</p><p>VS Code 里终端唤不起来时，先对 <a href="https://help.aliyun.com/zh/lingma/description-of-terminal-execution-exception" target="_blank" rel="noreferrer">终端执行异常说明</a>：官方写明 VS Code 插件依赖 Shell 集成 API，需要 <strong>VS Code &gt; 1.93</strong>，且默认终端是受支持的 shell。这和「插件安装要求 1.68.0」不是同一条门槛。</p><h2 id="给智能体接-mcp" tabindex="-1">给智能体接 MCP <a class="header-anchor" href="#给智能体接-mcp" aria-label="Permalink to &quot;给智能体接 MCP&quot;">​</a></h2><p>目标：让智能体调用外部工具（设计稿、文档、数据库 schemas）。</p><p>官方能力边界（<a href="https://help.aliyun.com/zh/lingma/guide-for-using-mcp" target="_blank" rel="noreferrer">MCP</a>）：</p><blockquote><p>MCP（Model Context Protocol）是一种开放标准协议，使其智能体的能力和场景得到拓展。</p><p>热门 MCP 市场： <a href="https://www.modelscope.cn/mcp" target="_blank" rel="noreferrer">魔搭社区 MCP 市场</a> 、 <a href="https://mcp.higress.ai/" target="_blank" rel="noreferrer">Higress MCP 市场</a> 。</p><p>热门场景：数据库 schemas / DAO；在线文档；根据设计稿生成前端代码。</p></blockquote><p>在 IntelliJ 里进入 MCP 页的官方步骤（<a href="https://help.aliyun.com/zh/lingma/use-lingma-mastergo-mcp-to-transforming-mastergo-design-draft-into-front-end-code" target="_blank" rel="noreferrer">MasterGo 示例</a>，侧栏图标在旧文档里仍写「通义灵码」）：</p><ol><li>单击 IDE 侧边栏图标进入 <strong>智能会话</strong>。</li><li>进入 <strong>MCP 服务</strong> 页：欢迎语里的 <strong>MCP 工具</strong> 链接，或右上角头像 → <strong>个人设置</strong> → <strong>MCP 服务</strong>。</li><li>切到 <strong>智能体</strong> 模式，再写提示词。</li><li>智能体要调 MCP 时会先询问；点执行后，返回结果进入后续上下文。</li></ol><p>不要把 Marketplace 评测里的第三方 JSON 当成官方配置格式。配置项以 <a href="https://help.aliyun.com/zh/lingma/guide-for-using-mcp" target="_blank" rel="noreferrer">MCP 指南</a> 打开的页为准。</p><h2 id="打开行间建议预测-nes" tabindex="-1">打开行间建议预测（NES） <a class="header-anchor" href="#打开行间建议预测-nes" aria-label="Permalink to &quot;打开行间建议预测（NES）&quot;">​</a></h2><p>目标：改完一处之后，让它预测下一处修改。</p><p>官方定义（<a href="https://help.aliyun.com/zh/lingma/next-edit-suggestion" target="_blank" rel="noreferrer">行间建议预测</a>）：基于当前完整代码上下文，结合代码修改和光标位置动态预测变更；<strong>Tab</strong> 接受，<strong>Esc</strong> 拒绝。</p><p>开启入口同一页写：用快捷键 <code>⌘ ⇧ ,</code>（macOS）或 <code>Ctrl Shift ,</code>（Windows）打开个人设置，开启 <strong>行间建议预测（NES）</strong>。并写明：<strong>Qoder CN IDE 仅支持 Auto 模式</strong>。</p><p>帮助中心更新日志里，IDE 侧 NES 曾升级为 <strong>NEXT</strong>。若设置页已改名，以你装的客户端设置为准，不要混用旧教程截图。</p><h2 id="常见坑" tabindex="-1">常见坑 <a class="header-anchor" href="#常见坑" aria-label="Permalink to &quot;常见坑&quot;">​</a></h2><table tabindex="0"><thead><tr><th>症状</th><th>先查什么</th><th>来源</th></tr></thead><tbody><tr><td>插件市场搜「通义灵码」找不到 / 搜「Qoder CN」找不到</td><td>营销站和帮助中心用的展示名不同，按你打开的那一页原文搜</td><td><a href="https://lingma.aliyun.com/download" target="_blank" rel="noreferrer">下载页</a>、<a href="https://help.aliyun.com/zh/lingma/installation-guide" target="_blank" rel="noreferrer">安装指南</a></td></tr><tr><td>VS Code 侧栏没有入口</td><td>侧栏右键，勾选 Qoder CN</td><td><a href="https://help.aliyun.com/zh/lingma/installation-guide" target="_blank" rel="noreferrer">安装指南</a></td></tr><tr><td>JetBrains / Lingma IDE 找不到「文件编辑」</td><td>这两端官方不支持该模式，用智能体</td><td><a href="https://help.aliyun.com/zh/lingma/overview-of-chat" target="_blank" rel="noreferrer">智能会话概览</a></td></tr><tr><td>VS Code 智能体跑不了终端</td><td>VS Code &gt; 1.93 + 受支持的 shell 集成</td><td><a href="https://help.aliyun.com/zh/lingma/description-of-terminal-execution-exception" target="_blank" rel="noreferrer">终端异常</a></td></tr><tr><td>还在用旧 Lingma IDE，功能对不上</td><td>官方升级路径：卸载原 Lingma IDE，改装 Qoder CN IDE</td><td><a href="https://help.aliyun.com/zh/lingma/billing-description" target="_blank" rel="noreferrer">计费说明</a></td></tr><tr><td>把它当成通义千问来聊天</td><td>走错产品。千问是对话助手，见<a href="./">学习地图</a></td><td><a href="https://www.qianwen.com/" target="_blank" rel="noreferrer">qianwen.com</a></td></tr></tbody></table>`,36)])])}const u=e(o,[["render",l]]);export{b as __pageData,u as default};
